const v = msg.payload?.values?.temperature;
if (typeof v !== 'number' || v <= 35) return null;
const [, site, gateway] = msg.topic.split('/');
if (!site || !gateway) return null;
const actual = msg.payload?.actuators?.fan;
let pending = flow.get('fanAutoPending');
if (typeof actual === 'boolean' && pending === actual) {
    pending = null;
    flow.set('fanAutoPending', null);
    flow.set('fanAutoState', actual ? 'on' : 'off');
}
const knownOn = typeof actual === 'boolean' ? actual : flow.get('fanAutoState') === 'on';
if (pending === true || (knownOn && pending !== false)) return null;
flow.set('fanAutoPending', true);
flow.set('fanAutoState', 'on');
const command = { action: 'turn_on', target: 'fan', source: 'local_rule', reason: 'temperature_above_35', temperature: v };
const alert = { severity: 'warning', type: 'overheat', message: `Temperature ${v}°C is above the fan-on threshold (35°C); requesting fan ON.`, device_id: msg.payload.device_id, timestamp: new Date().toISOString() };
return [{ payload: command, topic: `local/${site}/${gateway}/command` }, { payload: alert, topic: `smarthome/${site}/${gateway}/alerts` }];

const v = msg.payload?.values?.temperature;
if (typeof v !== 'number' || v >= 25) return null;
const [, site, gateway] = msg.topic.split('/');
if (!site || !gateway) return null;
const actual = msg.payload?.actuators?.fan;
let pending = flow.get('fanAutoPending');
if (typeof actual === 'boolean' && pending === actual) {
    pending = null;
    flow.set('fanAutoPending', null);
    flow.set('fanAutoState', actual ? 'on' : 'off');
}
const knownOn = typeof actual === 'boolean' ? actual : flow.get('fanAutoState') === 'on';
if (pending === false || (!knownOn && pending !== true)) return null;
flow.set('fanAutoPending', false);
flow.set('fanAutoState', 'off');
const command = { action: 'turn_off', target: 'fan', source: 'local_rule', reason: 'temperature_below_25', temperature: v };
const alert = { severity: 'info', type: 'fan_auto_off', message: `Temperature ${v}°C is below the fan-off threshold (25°C); requesting fan OFF.`, device_id: msg.payload.device_id, timestamp: new Date().toISOString() };
return [{ payload: command, topic: `local/${site}/${gateway}/command` }, { payload: alert, topic: `smarthome/${site}/${gateway}/alerts` }];

const p = msg.payload;
const parts = msg.topic.split('/');
if (!p || !['turn_on','turn_off'].includes(p.action) || !['fan','light'].includes(p.target)) return null;
if (parts.length !== 4 || parts[0] !== 'smarthome' || !parts[1] || !parts[2] || parts[3] !== 'command') return null;
msg.topic = `local/${parts[1]}/${parts[2]}/command`;
msg.payload = { action: p.action, target: p.target, source: 'cloud', device_id: p.device_id };
return msg;
